test_setup_files.test_matrix.cpp:
#include "matrix.h"
#include <cassert>
#include <iostream>

int main() {
    // non-square, so a coordinate-swap bug or a wrong-shape bug both show up
    Matrix m({{1, 2, 3}, {4, 5, 6}});
    Matrix t = m.transpose();

    assert(t.rows() == 3);
    assert(t.cols() == 2);
    assert(t.at(0, 0) == 1 && t.at(0, 1) == 4);
    assert(t.at(1, 0) == 2 && t.at(1, 1) == 5);
    assert(t.at(2, 0) == 3 && t.at(2, 1) == 6);

    // transposing twice returns the original shape and values
    Matrix tt = t.transpose();
    assert(tt.rows() == 2 && tt.cols() == 3);
    for (int r = 0; r < 2; r++) {
        for (int c = 0; c < 3; c++) {
            assert(tt.at(r, c) == m.at(r, c));
        }
    }

    // single row / single column edge cases
    Matrix row({{7, 8, 9}});
    Matrix rowT = row.transpose();
    assert(rowT.rows() == 3 && rowT.cols() == 1);
    assert(rowT.at(0, 0) == 7 && rowT.at(1, 0) == 8 && rowT.at(2, 0) == 9);

    std::cout << "PASS" << std::endl;
    return 0;
}

