#pragma once
#include <vector>

class Matrix {
public:
    explicit Matrix(std::vector<std::vector<int>> data) : data_(std::move(data)) {}

    int rows() const { return (int)data_.size(); }
    int cols() const { return data_.empty() ? 0 : (int)data_[0].size(); }
    int at(int r, int c) const { return data_[r][c]; }

    // Returns a new Matrix with rows/cols swapped: result(c, r) == this->at(r, c).
    Matrix transpose() const {
        std::vector<std::vector<int>> result(cols(), std::vector<int>(rows()));
        for (int r = 0; r < rows(); r++) {
            for (int c = 0; c < cols(); c++) {
                result[c][r] = data_[r][c];
            }
        }
        return Matrix(result);
    }

private:
    std::vector<std::vector<int>> data_;
};

